def generate(rng, n):
    intervals = []
    curr = 0
    for _ in range(n):
        start = curr + rng.randint(1, 3)
        end = start + rng.randint(1, 3)
        intervals.append([start, end])
        curr = end
    if n > 0:
        idx = rng.randint(0, n - 1)
        new_interval = [intervals[idx][0], intervals[idx][1] + rng.randint(1, 5)]
    else:
        new_interval = [1, 5]
    return [intervals, new_interval]

def generate_worst(rng, n):
    intervals = [[i * 4, i * 4 + 2] for i in range(n)]
    new_interval = [0, n * 4 + 10]
    return [intervals, new_interval]

